class _ContextBacking:
    __slots__ = ('data', 'owners')

    def __init__(self, data=None):
        self.data = {} if data is None else data
        self.owners = 1


class ContextMap:
    """Copy-on-write value map for clone snapshots.

    Context values are immutable. A clone therefore needs an independent view,
    not an eager dictionary copy: only a later insertion/removal detaches it.
    This keeps repeated fork/exit audit streams proportional to events rather
    than to the number of inherited contexts.
    """
    __slots__ = ('_backing',)

    def __init__(self, backing=None):
        self._backing = backing or _ContextBacking()

    def clone(self):
        self._backing.owners += 1
        return ContextMap(self._backing)

    def _own(self):
        if self._backing.owners > 1:
            old = self._backing
            old.owners -= 1
            self._backing = _ContextBacking(dict(old.data))

    def get(self, key, default=None):
        return self._backing.data.get(key, default)

    def __setitem__(self, key, value):
        self._own()
        self._backing.data[key] = value

    def pop(self, key):
        self._own()
        return self._backing.data.pop(key)

    def __len__(self):
        return len(self._backing.data)

    def values(self):
        return self._backing.data.values()

    def release(self):
        if self._backing.owners:
            self._backing.owners -= 1

